\label{thm:A}
Let $\mathfrak{g}$ be a complex simple Lie algebra with dual Coxeter number $h^\vee$. For compact real form $\mathfrak{g}_{0}$ with associated compact conjugation $\tau$ and Hermitian form $H$, 
\begin{align}\label{eq:main}
\lVert [x,y]\rVert^{2} \leq \frac{1}{h^\vee}\lVert x\rVert^{2}\lVert y\rVert^{2} \qquad \text{for all}\,\, x, y \in \mathfrak{g},
\end{align}
and the constant is optimal. If $x, y \neq 0$, then equality holds in \eqref{eq:main} if and only if $H(x, y) = 0$ and $x$ and $y$ are contained in a $\tau$-stable subalgebra $\mathfrak{s} \subset \mathfrak{g}$ isomorphic to $\mathfrak{sl}(2, \mathbb C)$ and having Dynkin index $1$.

\label{ex:eh}
Let $\mathfrak{g} = \mathfrak{sl}(2, \mathbb C)$ and $\mathfrak{g}_{0} = \mathfrak{su}(2)$, so that $\tau X = -X^{\dagger}$, $H(X, Y) = 4\operatorname{tr} XY^{\dagger}$, and $h^\vee = 2$. For $e = E_{12}$ and $h = E_{11} - E_{22}$, $H(e, h) = 0$, $\lVert e\rVert^{2} = 4$, $\lVert h\rVert^{2} = 8$, and $[e, h] = -2e$, so
\begin{align}\label{eq:ehnorms}
\frac{\lVert [e, h]\rVert^{2}}{\lVert e\rVert^{2}\lVert h\rVert^{2}} = \frac{16}{32} = \frac{1}{h^\vee},
\end{align}
and, by \eqref{eq:ehnorms}, equality holds in \eqref{eq:main}. However, $e$ and $h$ generate the two-dimensional subalgebra $\mathbb C e \oplus \mathbb C h$, which is not $\tau$-stable. Thus in Theorem \ref{thm:A} ``contained in'' cannot be replaced by ``generate''. The same happens in every complex simple Lie algebra $\mathfrak{g}$: for $0 \neq e \in \mathfrak{g}_{\theta}$, where $\theta$ is the highest root, $H(e, \theta^{\vee}) = 0$ and $e$ and $\theta^{\vee}$ lie in the $\tau$-stable subalgebra of Dynkin index $1$ attached to $\theta$, so equality holds in \eqref{eq:main} by Lemmas \ref{lem:sl2str}\ref{sl2b} and \ref{lem:lower}\ref{lower2}, while $e$ and $\theta^{\vee}$ generate the subalgebra $\mathfrak{g}_{\theta} \oplus \mathbb C\theta^{\vee}$, which is not $\tau$-stable.

\label{thm:B}
Let $\rho:\mathfrak{g} \to \mathfrak{gl}(V)$ be a nonzero representation of the complex simple Lie algebra $\mathfrak{g}$ with Dynkin index $\ell_{\rho}$, let $V$ carry a Hermitian inner product invariant under the compact real form $\mathfrak{g}_{0}$, and let $\lVert X\rVert_{F}^{2} = \operatorname{tr} XX^{\dagger}$ be the corresponding Frobenius norm on $\mathfrak{gl}(V)$. Then
\begin{align}\label{eq:repbound}
\lVert [X, Y]\rVert_{F}^{2} \leq \frac{2}{\ell_{\rho}}\lVert X\rVert_{F}^{2}\lVert Y\rVert_{F}^{2} \qquad \text{for all}\,\, X, Y \in \rho(\mathfrak{g}),
\end{align}
the constant is optimal, and the equality case is the image under $\rho$ of the equality case of Theorem \ref{thm:A}.

\label{thm:comass}
Let $\mathfrak{g}$ be a complex simple Lie algebra with dual Coxeter number $h^\vee$. For compact real form $\mathfrak{g}_{0}$ with associated compact conjugation $\tau$ and Hermitian form $H$, the comass of the Cartan $3$-form $\omega$ with respect to the Hermitian form $H$ on $\mathfrak{g}$ equals its comass with respect to the Euclidean form $-B$ on $\mathfrak{g}_{0}$,
\begin{align}\label{eq:comassintro}
\begin{aligned}
\lVert \omega\rVert_{\ast} &= \sup\big\{|\omega(x, y, z)|: x, y, z \in \mathfrak{g},\ \lVert x\rVert = \lVert y\rVert = \lVert z\rVert = 1\big\}\\
&= \sup\big\{\omega(x, y, z): x, y, z \in \mathfrak{g}_{0},\ \lVert x\rVert = \lVert y\rVert = \lVert z\rVert = 1\big\} = (h^\vee)^{-1/2}.
\end{aligned}
\end{align}

\label{thm:C}
Let $\mathfrak{g}$ be a complex simple Lie algebra with compact conjugation $\tau$ and Nahm algebra $(\mathfrak{g}^{3}, \circledcirc)$, and extend $H$ and $\tau$ to $\mathfrak{g}^{3}$ componentwise.
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{thmC1} Up to the action of $(\mathbb C^{\ast})^{3}$ by rescaling of components, the critical points of $W$ at which $W$ is nonzero are the nonzero $\tau$-twisted idempotents $e \in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$, and the corresponding critical value is $W(e) = \tfrac{3}{4}H(e, e)^{-1}$.
\item\label{thmC2} Every nonzero $\tau$-twisted idempotent $e \in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$ satisfies $H(e, e) \geq \tfrac{3}{4}h^\vee$, with equality if and only if the components of $e$ span a $\tau$-stable subalgebra isomorphic to $\mathfrak{sl}(2, \mathbb C)$ of Dynkin index $1$.
\end{enumerate}

\label{lem:dynkinformula}
\leavevmode\noindent
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{dynkinformula1} The normalized form of $\mathfrak{sl}(n, \mathbb C)$, $n \geq 2$, is $(X, Y)_{\mathfrak{sl}(n, \mathbb C)} = \operatorname{tr} XY$. Consequently, for a nonzero representation $\rho:\mathfrak{g} \to \mathfrak{gl}(V)$,
\begin{align}\label{eq:repindex}
\operatorname{tr} \rho(x)\rho(y) = \ell_{\rho}\,(x, y), \qquad x, y \in \mathfrak{g}.
\end{align}
\item\label{dynkinformula2} If $\mathfrak{s} \subset \mathfrak{g}$ is a subalgebra isomorphic to $\mathfrak{sl}(2, \mathbb C)$ and $(e, f, h)$ is an $\mathfrak{sl}(2, \mathbb C)$-triple spanning $\mathfrak{s}$, then
\begin{align}\label{eq:dynkinindex}
j(\mathfrak{s}) = \frac{(h, h)}{2} = \frac{B(h, h)}{4h^\vee}.
\end{align}
\end{enumerate}

The operator $\operatorname{ad}(h)$ is diagonalizable with integer eigenvalues, because $\mathfrak{g}$ is a finite-dimensional module for $\operatorname{Span}\{e, f, h\}$; in particular $h$ is semisimple. By \ref{R3}, after conjugating the whole triple $(e, f, h)$ by an element of the adjoint group, which preserves $B$ and the relations \eqref{eq:sl2triple}, it can be assumed that $h \in \mathfrak{h}$. The roots take integer values on $h$, because these values are eigenvalues of $\operatorname{ad}(h)$, so $h$ lies in the real span of the coroots, and by the second part of \ref{R3}, after conjugating the triple by an element of the adjoint group representing an element of the Weyl group, $h$ can be assumed dominant. Since $[h,e]=2e$ with $e\ne0$, $\mu(h)=2$ for some root $\mu$, so $\theta(h)\ge2$ by \ref{R1}. By the Cauchy--Schwarz inequality for the positive definite form $(\,\cdot\,\,, \,\cdot\,\,)$ on the real span of the coroots,
\begin{align}\label{eq:CSh}
4 \leq \theta(h)^2=(\theta^\vee,h)^2\le(\theta^{\vee},\theta^{\vee})(h,h)=2(h,h),
\end{align}
so $(h,h)\ge2$ and $B(h,h)=2h^\vee(h,h)\ge4h^\vee$ by \eqref{eq:Bnorm}. If $(h, h) = 2$, then equality holds throughout \eqref{eq:CSh}, so $h = c\theta^{\vee}$ with $c > 0$ and $2 = \theta(h) = 2c$. Conversely $B(\theta^\vee,\theta^\vee)=2h^\vee(\theta^{\vee},\theta^{\vee}) = 4h^\vee$. If $h = \theta^{\vee}$, then $e \in \mathfrak{g}_{\theta}$ and $f \in \mathfrak{g}_{-\theta}$, because $\theta$ is the only root taking the value $2$ on $\theta^{\vee}$ (the equality case of \eqref{eq:CSh} applied to the roots $\mu$ with $\mu(\theta^{\vee}) = 2$). Together with \eqref{eq:dynkinindex}, this shows that a subalgebra $\mathfrak{s} \simeq \mathfrak{sl}(2, \mathbb C)$ has $j(\mathfrak{s}) = 1$ if and only if it is conjugate to $\mathfrak{s}_{\theta}$.

For the remaining claims, $\mathfrak{s}_{\mu}$ is spanned by an $\mathfrak{sl}(2, \mathbb C)$-triple with neutral element $\mu^{\vee}$, and $(\mu^{\vee}, \mu^{\vee}) = 4/(\mu, \mu)$, so $j(\mathfrak{s}_{\mu}) = 2/(\mu, \mu)$ by \eqref{eq:dynkinindex}, and this is $1$ if and only if $\mu$ is long by \ref{R1}. The Dynkin index is invariant under conjugation. If $j(\mathfrak{s}) = 1$, then $\mathfrak{s}$ is conjugate to $\mathfrak{s}_{\theta}$, which is a long-root subalgebra by definition. Conversely, if $\mathfrak{s} = \operatorname{Ad}(g)\mathfrak{s}_{\mu}$ with $\mu$ long, then, because the Weyl group acts transitively on the long roots and is realized by the normalizer of $\mathfrak{t}_{0}$ in $G_{0}$, there is $n \in G_{0}$ with $\operatorname{Ad}(n)\mathfrak{s}_{\mu} = \mathfrak{s}_{\theta}$; hence $\mathfrak{s}$ is conjugate to $\mathfrak{s}_{\theta}$ and $j(\mathfrak{s}) = j(\mathfrak{s}_{\theta}) = 1$.

\label{lem:sl2str}
Let $\mathfrak{s}\subset\mathfrak{g}$ be a $\tau$-stable subalgebra isomorphic to $\mathfrak{sl}(2, \mathbb C)$, with Dynkin index $j$, and let $\beta := jh^\vee$.
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{sl2a} $\mathfrak{s}_0:=\mathfrak{s}\cap\mathfrak{g}_{0}$ is a compact real form of $\mathfrak{s}$, and it has a basis $z_1,z_2,z_3$ such that
\begin{align}\label{eq:xirelations}
[z_{1}, z_{2}] &= z_{3}, \quad [z_{2}, z_{3}] = z_{1}, \quad [z_{3}, z_{1}] = z_{2}, & B(z_a,z_b) &= -\beta\,\delta_{ab}, & a, b &\in \{1, 2, 3\}.
\end{align}
For such a basis $(e, f, h) := (z_{1} + iz_{2}, -z_{1} + iz_{2}, 2iz_{3})$ is an $\mathfrak{sl}(2, \mathbb C)$-triple with $\tau e = -f$ and $\tau h = -h$.
\item\label{sl2b} For all $x, y \in \mathfrak{s}$,
\begin{align}\label{eq:sl2norm}
\lVert [x,y]\rVert^2 = \frac{1}{\beta}\Big(\lVert x\rVert^{2}\lVert y\rVert^{2} - |H(x, y)|^{2}\Big).
\end{align}
\end{enumerate}

\label{rem:comass}
The quantity \eqref{eq:comass} is a comass in the usual sense \cite{Harvey-Lawson}: for a real alternating form on a Euclidean space, the supremum over unit vectors equals the maximum over orthonormal frames, by Hadamard's inequality. Regard $\mathfrak{g}$ as the Euclidean space $(\mathfrak{g}^{\mathbb R}, \operatorname{Re} H)$, on which $\operatorname{Re}\omega$ is a real alternating trilinear form. Since $\operatorname{Re}\omega \leq |\omega|$, and replacing $x$ by $e^{i\phi}x$ makes $\omega(x, y, z)$ real and nonnegative,
\begin{align}\label{eq:comassreal}
\lVert \omega\rVert_{\ast} = \sup\big\{\operatorname{Re}\omega(x, y, z): \lVert x\rVert = \lVert y\rVert = \lVert z\rVert = 1\big\} = \lVert \operatorname{Re}\omega\rVert_{\ast},
\end{align}
the comass of $\operatorname{Re}\omega$ on $(\mathfrak{g}^{\mathbb R}, \operatorname{Re} H)$. On the other hand, $\omega$ restricted to $\mathfrak{g}_{0}$ is a real alternating form on the Euclidean space $(\mathfrak{g}_{0}, -B)$, whose comass is the quantity studied by Tasaki \cite{Tasaki-calibration} (Remark \ref{rem:calibration}). By \eqref{eq:comassreal} and Corollary \ref{thm:compact}\ref{compact1} below, Theorem \ref{thm:A} asserts that these two comasses are equal, both being $(h^\vee)^{-1/2}$.

In the language of tensors, \eqref{eq:comass} is the injective norm of $\omega$ regarded as a complex $3$-tensor on the Hermitian space $(\mathfrak{g}, H)$, which in the literature on tensor computations and optimization is called the \emph{spectral norm}; for alternating tensors it coincides with the comass, by the Hadamard argument above. For tensors of order at least $3$, the spectral norm of a real tensor depends in general on whether the tensor is regarded as real or as complex \cite{Friedland-Lim-nuclear}. The restriction of $\omega$ to $\mathfrak{g}_{0}$ is a real $3$-tensor on $(\mathfrak{g}_{0}, -B)$ whose complexification is $\omega$ on $(\mathfrak{g}, H)$, and by Theorem \ref{thm:A} and Corollary \ref{thm:compact}\ref{compact1} its complex and real spectral norms coincide. This is a property of the Cartan form, not a formal consequence of the definitions.

The relevance of comass to inequalities of DDVV type was observed by Choi and Lu \cite{Choi-Lu}, who used calibrations to prove cases of the DDVV inequality; the present paper goes in the other direction, using the extremal problem for the commutator to compute the comass of the Cartan $3$-form on the Hermitian space $(\mathfrak{g}, H)$.

\label{fkwmaxlemma}
\leavevmode\noindent
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{fkw1} $F(x, y) \leq \mathscr{K}(x, y)$ for $(x, y) \in \mathscr{V}(\mathfrak{g})$, with equality if and only if $H(x, y) = 0$ or $[x, y] = 0$.
\item\label{fkw2} $W(x, y, z) \leq F(x, y)$, with equality if and only if $[x, y] = 0$ or $z \in \mathbb C\,\tau[x, y]$. In particular $F(x,y)=\max_{z \in \mathfrak{g} \setminus \{0\}}W(x,y,z)$.
\item\label{fkw3} $F$, $\mathscr{K}$, and $W$ attain their suprema, and
\begin{align}\label{eq:fkwcomass}
\max_{\sigma \in \operatorname{Gr}(2, \mathfrak{g})} \mathscr{K}(\sigma) = \max_{x, y \in \mathfrak{g} \setminus \{0\}} F(x, y) = \max_{x, y, z \in \mathfrak{g} \setminus \{0\}} W(x, y, z) =\lVert \omega\rVert_{\ast}^2 > 0.
\end{align}
\end{enumerate}

Claim \ref{fkw1} is clear from \eqref{eq:FKWdef}, and \ref{fkw2} is the Cauchy--Schwarz inequality, by \eqref{eq:omegaformulas},
\begin{align}\label{eq:Fomega1}
|\omega(x,y,z)|^{2} = |H([x, y], \tau z)|^{2} \leq \lVert [x, y]\rVert^{2}\lVert z\rVert^{2},
\end{align}
with its equality case, divided by $\lVert x\rVert^{2}\lVert y\rVert^{2}\lVert z\rVert^{2}$. For \ref{fkw3}, the three functions descend to compact manifolds, so attain their maxima; $\max\mathscr{K} = \max F$ because every plane has an $H$-orthogonal basis, on which $F = \mathscr{K}$; $\max F = \max W = \lVert \omega\rVert_{\ast}^{2}$ by \eqref{eq:Fomega1} and \eqref{eq:comass}, which gives \eqref{eq:fkwcomass}; and the maximum is positive because $\mathfrak{g}$ is not abelian.

\label{cor:vinberg}
For every $\operatorname{Ad}(G_{0})$-invariant norm $N$ on $\mathfrak{g}_{0}$,
\begin{align}\label{eq:vinbergbound}
\sup_{x, y \in \mathfrak{g}_{0}\setminus\{0\}}\frac{N([x, y])}{N(x)N(y)} = \max_{\alpha \in \Phi}\,\max\big\{|\alpha(t)|: t \in \mathfrak{t}_{0},\ N(t) = 1\big\}.
\end{align}

\label{thm:compact}
\leavevmode\noindent
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{compact1} For $x \in \mathfrak{g}_{0}\setminus\{0\}$, $\sup_{y \in \mathfrak{g} \setminus \{0\}}F(x, y)$ is attained at some $y \in \mathfrak{g}_{0}$, and $F(x, y) \leq 1/h^\vee$ for all $x \in \mathfrak{g}_{0}\setminus\{0\}$ and $y \in \mathfrak{g} \setminus \{0\}$, with equality for some $x, y \in \mathfrak{g}_{0}$.
\item\label{compact2} A pair $(x, y) \in (\mathfrak{g}_{0} \setminus \{0\})^{2}$ satisfies $F(x, y) = 1/h^\vee$ if and only if it is $\operatorname{Ad}(G_{0})$-conjugate to a pair $(c s_{\theta}, y')$ with $c \in \mathbb R \setminus \{0\}$ and $0 \neq y' \in \mathfrak{g}_{0} \cap (\mathfrak{g}_{\theta} \oplus \mathfrak{g}_{-\theta})$.
\end{enumerate}

\label{rem:calibration}
A closed $p$-form is a calibration if its comass, its maximum on unit simple $p$-vectors, is at most $1$ \cite{Harvey-Lawson}. Tasaki \cite[Theorem~5]{Tasaki-calibration} proved that on a compact simple Lie group with bi-invariant metric $-B$, the bi-invariant $3$-form 
\begin{align}\label{eq:tasakiform}
\phi(x, y, z) = (h^\vee)^{1/2}\,(-B)([x, y], z) = -(h^\vee)^{1/2}\,\omega(x, y, z), \qquad x, y, z \in \mathfrak{g}_{0},
\end{align}
(normalized there by the length $(h^\vee)^{-1/2}$ of the highest root for the metric $-B$; see \eqref{eq:salpha}) is a calibration, whose calibrated $3$-planes are exactly the $\operatorname{Ad}(G_{0})$-conjugates of the long-root subalgebra $\mathfrak{su}(2) \subset \mathfrak{g}_{0}$, suitably oriented. Ohnita and Tasaki \cite[Theorem~2 and Lemma~5]{Ohnita-Tasaki} showed that every submanifold calibrated by $\phi$ is totally geodesic, hence an open piece of a congruent copy of the long-root subgroup, so that this subgroup is, up to congruence, the unique volume minimizer in its real homology class. Since calibrated planes exist, the calibration property says that the comass of $\omega$ with respect to the Euclidean form $-B$ on $\mathfrak{g}_{0}$ is $(h^\vee)^{-1/2}$, in agreement with Corollary \ref{thm:compact}\ref{compact1}. See also \cite{Hitchin-calibrations}, where the calibration \eqref{eq:tasakiform} and its relation with the principal three-dimensional subgroup are discussed.

\label{lem:nahmbasic}
Let $\mathsf{L}:\mathfrak{g}^{3} \to \operatorname{End}(\mathfrak{g}^{3})$ be the multiplication endomorphism of the Nahm algebra $(\mathfrak{g}^{3}, \circledcirc)$ defined by $\mathsf{L}(a)b := a \circledcirc b$. 
For $a, b, c \in \mathfrak{g}^{3}$:
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{nahm1} $\circledcirc$ is complex bilinear and commutative, and $B(a \circledcirc b, c)$ is the full polarization of $C$:
\begin{align}\label{eq:polarization}
B(a \circledcirc b, c) = C(a + b + c) - C(a+b) - C(b+c) - C(c+a) + C(a) + C(b) + C(c).
\end{align}
In particular $B(a \circledcirc b, c)$ is symmetric in $a$, $b$, $c$, so $B$ is invariant: $B(a \circledcirc b, c) = B(a, b \circledcirc c)$.
\item\label{nahm2} $a \circledcirc a = 2\big([a_{2}, a_{3}], [a_{3}, a_{1}], [a_{1}, a_{2}]\big)$, and the first and second derivatives of $C$ at $a$ are
\begin{align}\label{eq:derivativesC}
dC_{a}(b) = \tfrac{1}{2}B(a \circledcirc a, b), \qquad d^{2}C_{a}(b, c) = B(a \circledcirc b, c).
\end{align}
\item\label{nahm3} $\tau$ is a conjugate-linear order $2$ automorphism of $(\mathfrak{g}^{3}, \circledcirc)$ and $H(a\circledcirc b, c) = H(b, \tau a \circledcirc c)$; that is, the $H$-adjoint $\mathsf{L}(a)^{\dagger}$ of $\mathsf{L}(a)$ satisfies $\mathsf{L}(a)^{\dagger} = \mathsf{L}(\tau a)$.
\item\label{nahm4} $\operatorname{tr} \mathsf{L}(a) = 0$.
\end{enumerate}

\label{lem:critW}
An element $a \in (\mathfrak{g} \setminus\{0\})^{3}$ with $C(a) \neq 0$ lies in $\mathrm{Crit}^*(W)$ if and only if
\begin{align}\label{eq:W}
&[a_{1}, a_{2}] = -\frac{C(a)}{\lVert a_{3}\rVert^{2}}\tau a_{3},&
&[a_{2}, a_{3}] = -\frac{C(a)}{\lVert a_{1}\rVert^{2}}\tau a_{1},&
&[a_{3}, a_{1}] = -\frac{C(a)}{\lVert a_{2}\rVert^{2}}\tau a_{2}.&
\end{align}
Equivalently, $a \in (\mathfrak{g} \setminus\{0\})^{3}$ lies in $\mathrm{Crit}^*(W)$ if and only if $C(a) \neq 0$ and $a \circledcirc a \in (\mathbb C^{\ast})^{3}\cdot \tau a$.

Let $a \in (\mathfrak{g}\setminus\{0\})^{3}$ satisfy $C(a) \neq 0$, and let $\Pi(a) := \prod_{i=1}^{3}\lVert a_{i}\rVert^{2}$. For $b \in \mathfrak{g}^{3}$, by \eqref{eq:derivativesC}, 
\begin{align}\label{eq:dC}
d(|C|^{2})_{a}(b) = 2\operatorname{Re}\big(\overline{C(a)}\tfrac{1}{2}B(b, a \circledcirc a)\big) = -\operatorname{Re} H(b, C(a)\tau(a \circledcirc a)),
\end{align}
while 
\begin{align}\label{eq:dPi}
d\Pi_{a}(b) = 2\Pi(a)\sum_{i=1}^{3}\operatorname{Re} H(b_{i}, a_{i})/\lVert a_{i}\rVert^{2}. 
\end{align}
Since $W(a) = |C(a)|^{2}/\Pi(a)$, \eqref{eq:dC} and \eqref{eq:dPi} show 
\begin{align}\label{eq:dW}
dW_{a}(b) = -\frac{1}{\Pi(a)}\operatorname{Re} H\big(b, C(a)\tau(a \circledcirc a)\big) - 2W(a)\sum_{i=1}^{3}\frac{\operatorname{Re} H(b_{i}, a_{i})}{\lVert a_{i}\rVert^{2}}.
\end{align}
Because $\operatorname{Re} H$ is nondegenerate and $W(a)\Pi(a) = |C(a)|^{2}$, by \eqref{eq:dW}, $dW_{a} = 0$ if and only if $C(a)\tau(a \circledcirc a)_{i} = -2|C(a)|^{2}a_{i}/\lVert a_{i}\rVert^{2}$ for each $i$, that is, $(a \circledcirc a)_{i} = -2C(a)\tau a_{i}/\lVert a_{i}\rVert^{2}$, which yields \eqref{eq:W} by Lemma \ref{lem:nahmbasic}\ref{nahm2}.

By \eqref{eq:W}, if $a \in \mathrm{Crit}^*(W)$, then $a \circledcirc a \in (\mathbb C^{\ast})^{3}\cdot \tau a$. If $C(a) \neq 0$ and $a \circledcirc a = c \cdot \tau a$ with $c \in (\mathbb C^{\ast})^{3}$, then $2[a_{1}, a_{2}] = c_{3}\tau a_{3}$ by Lemma \ref{lem:nahmbasic}\ref{nahm2}, so by \eqref{eq:omegaformulas}, $C(a) = B([a_{1}, a_{2}], a_{3}) = \tfrac{1}{2}c_{3}B(\tau a_{3}, a_{3}) = -\tfrac{1}{2}c_{3}\lVert a_{3}\rVert^{2}$, and $\tfrac{1}{2}c_{3} = -C(a)/\lVert a_{3}\rVert^{2}$. As the same identities hold when the indices are permuted cyclically, this shows \eqref{eq:W}, so $a \in \mathrm{Crit}^*(W)$.

\label{thm:idem}
\leavevmode\noindent
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{idem2} For $e\in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$, the components $e_{1}$, $e_{2}$, and $e_{3}$ are pairwise $H$-orthogonal, satisfy $\lVert e_{1}\rVert = \lVert e_{2}\rVert = \lVert e_{3}\rVert = 3^{-1/2}\lvert e\rvert > 0$, and, for distinct $i, j \in \{1, 2, 3\}$,
\begin{align}\label{eq:idemnorms}
 W(e) = F(e_{i}, e_{j}) =  \frac{3}{4H(e, e)} = -\frac{1}{8C(e)}.
\end{align}
\item\label{idem1} $\mathrm{Crit}^*(W) = (\mathbb C^{\ast})^{3}\cdot \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$.
\item\label{idem3} The Lie subalgebra $\mathfrak{s}$ of $\mathfrak{g}$ generated by the components of $e \in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$ is $\tau$-stable and semisimple. 
\end{enumerate}

By Lemma \ref{lem:nahmbasic}\ref{nahm2}, for $(i, j, k)$ a cyclic permutation of $(1, 2, 3)$, $e \circledcirc e = \tau e$ means that $2[e_{j}, e_{k}] = \tau e_{i}$. By the invariance of $B$, $2\omega(e_{i}, e_{j}, e_{k}) = 2C(e) = 2B(e_{i}, [e_{j}, e_{k}]) = B(e_{i}, \tau e_{i}) = -\lVert e_{i}\rVert^{2}$, so the components of $e$ have a common norm, which is positive because $e \neq 0$. Similarly $H(e_{i}, e_{j}) = -B(e_{i}, \tau e_{j}) = -2B(e_{i}, [e_{k}, e_{i}]) = 2B([e_{i}, e_{i}], e_{k}) = 0$. The identity \eqref{eq:idemnorms} and claim \ref{idem2} follow.

By \ref{idem2}, every $e \in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$ has nonzero components and $C(e) \neq 0$, so, since $e \circledcirc e = \tau e$, Lemma \ref{lem:critW} gives $(\mathbb C^{\ast})^{3}\cdot \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc) \subset \mathrm{Crit}^*(W)$. Each map $a \mapsto c\cdot a$, $c \in (\mathbb C^{\ast})^{3}$, is a linear automorphism of $\mathfrak{g}^{3}$ preserving $W$, so it maps critical points of $W$ to critical points of $W$. Let $a \in \mathrm{Crit}^*(W)$ and $c \in (\mathbb C^{\ast})^{3}$. By \eqref{caca}, \eqref{hatc}, \eqref{eq:W}, and the conjugate-linearity of $\tau$,
\begin{align}\label{cdotasquared}
\begin{aligned}
(c\cdot a)\circledcirc (c\cdot a) - \tau(c \cdot a) = \hat{c}\cdot (a\circledcirc a) - \bar{c}\cdot \tau a = -2C(a)\left(\tfrac{c_{2}c_{3}}{\lVert a_{1}\rVert^{2}}, \tfrac{c_{1}c_{3}}{\lVert a_{2}\rVert^{2}}, \tfrac{c_{1}c_{2}}{\lVert a_{3}\rVert^{2}} \right)\cdot \tau a - \bar{c}\cdot \tau a.
\end{aligned}
\end{align}
Let $z \in \mathbb C^{\ast}$ solve $z^{3} = -\tfrac{C(a)^{2}}{|C(a)|^{2}}$ and define $c \in (\mathbb C^{\ast})^{3}$ by
\begin{align}\label{eq:cchoice}
c = \tfrac{z}{2C(a)}\left(\lVert a_{2}\rVert\lVert a_{3}\rVert, \lVert a_{3}\rVert\lVert a_{1}\rVert, \lVert a_{1}\rVert\lVert a_{2}\rVert\right).
\end{align}
Writing $P := \lVert a_{1}\rVert\lVert a_{2}\rVert\lVert a_{3}\rVert$ and $\kappa := z/(2C(a))$, the choice \eqref{eq:cchoice} gives $c_{j}c_{k} = \kappa^{2}P\lVert a_{i}\rVert$ and $\bar{c}_{i} = \bar{\kappa}P/\lVert a_{i}\rVert$ for $\{i, j, k\} = \{1, 2, 3\}$, so the $i$th coefficient in \eqref{cdotasquared} is $-(2C(a)\kappa^{2} + \bar{\kappa})P/\lVert a_{i}\rVert$, which vanishes because $|z| = 1$ and $z^{3}\overline{C(a)} = -C(a)$. Hence \eqref{cdotasquared} equals $0$, so $c \cdot a \in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$ and $a = c^{-1}\cdot(c \cdot a) \in (\mathbb C^{\ast})^{3}\cdot\mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$. This shows \ref{idem1}. 

By \eqref{nahmproduct}, the components of $e \circledcirc e = \tau e$ are brackets of components of $e$, so they lie in $[\mathfrak{s}, \mathfrak{s}] \subset \mathfrak{s}$. Hence $\tau$ maps the generators of $\mathfrak{s}$, and so all iterated brackets of them, into $\mathfrak{s}$, and so $\tau\mathfrak{s} = \mathfrak{s}$ because $\tau^{2} = \operatorname{Id}_{\mathfrak{g}}$. Then $\mathfrak{s} = \mathfrak{s}_{0} \oplus i\mathfrak{s}_{0}$ with $\mathfrak{s}_{0} = \mathfrak{s} \cap \mathfrak{g}_{0}$, and $-B$ is a positive definite invariant inner product on $\mathfrak{s}_{0}$, so $\mathfrak{s}_{0}$, and hence $\mathfrak{s}$, is reductive, $\mathfrak{s} = \mathfrak{z}(\mathfrak{s}) \oplus [\mathfrak{s}, \mathfrak{s}]$. The components of $e = \tau(e \circledcirc e) = \tau e \circledcirc \tau e$ are brackets of components of $\tau e$, which lie in $\mathfrak{s}$, so they lie in $[\mathfrak{s}, \mathfrak{s}]$. Hence $\mathfrak{s} = [\mathfrak{s}, \mathfrak{s}]$, $\mathfrak{z}(\mathfrak{s}) = 0$, and $\mathfrak{s}$ is semisimple. This shows \ref{idem3}.

\label{hess2}
For $e \in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$ and $i \in \{1, 2, 3\}$, let $\hat{e}_{i} := \iota_{i}(e_{i}) \in \mathfrak{g}^{3}$ be the image of $e_{i}$ under the linear embedding of $\mathfrak{g}$ as the $i$th factor, and define
\begin{align}\label{eq:UR}
&U_{e} := \operatorname{Span}_{\mathbb R}\{\hat{e}_{i}, J\hat{e}_{i}: i \in \{1, 2, 3\}\}, &
&U^{\perp}_{e} = \{b \in \mathfrak{g}^{3}: H(b_{i}, e_{i}) = 0 \text{ for } i \in \{1, 2, 3\}\}.
\end{align}
Then $U^{\perp}_{e}$ is the orthogonal complement with respect to $\operatorname{Re} H$ of $U_{e}$ in $\mathfrak{g}^3$ and the real linear operator $\tau\mathsf{L}(e)$ is self-adjoint with respect to the real inner product $\operatorname{Re} H$, anticommutes with $J$, and preserves $U_{e}$ and $U^{\perp}_{e}$.

\label{thm:hessW}
Let $e \in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$, and let $U_{e}$ and $U^{\perp}_{e}$ be as in \eqref{eq:UR}. 
For $b \in \mathfrak{g}^{3}$, 
\begin{align}\label{eq:hessW}
\operatorname{Hess} W_{e}(b) = 16W(e)^{2}\Big(\operatorname{Re} H\big(b, (\tau\mathsf{L}(e) - \tfrac{1}{2})b\big) + 2W(e)\big(|H(b, e)|^{2} - 4(\eta_{1}\eta_{2} + \eta_{2}\eta_{3} + \eta_{3}\eta_{1})\big)\Big),
\end{align}
where $\eta_{i} := \operatorname{Re} H(b_{i}, e_{i})$ for $i \in \{1, 2, 3\}$.
In particular, for $b \in U^{\perp}_{e}$,
\begin{align}\label{eq:hessR}
\operatorname{Hess} W_{e}(b) = 16W(e)^{2}\operatorname{Re} H\big(b, (\tau\mathsf{L}(e) - \tfrac{1}{2})b\big),
\end{align}
and
\begin{align}\label{eq:hessJ}
\operatorname{Hess} W_{e}(b) + \operatorname{Hess} W_{e}(Jb) = -16W(e)^{2}\lvert b\rvert^{2}.
\end{align}
Moreover $\operatorname{Hess} W_{e}(u, b) = 0$ for $u \in U_{e}$ and $b \in \mathfrak{g}^{3}$, so $\operatorname{Hess} W_{e}(b) = \operatorname{Hess} W_{e}(b_{U^{\perp}_{e}})$, where $b_{U^{\perp}_{e}}$ is the orthogonal projection of $b$ on $U^{\perp}_{e}$, and $\operatorname{Hess} W_{e}(b_{U^{\perp}_{e}})$ is given by \eqref{eq:hessR}.

By \eqref{eq:idemnorms}, $C(e) = -1/(8W(e))$ and $\lVert e_{i}\rVert^{-2} = 4W(e)$ for $i \in \{1, 2, 3\}$. Let $b \in \mathfrak{g}^{3}$. From
\begin{align}
\lVert e_{i} + \varepsilon b_{i}\rVert^{2} = \lVert e_{i}\rVert^{2} + 2\varepsilon\operatorname{Re} H(b_{i}, e_{i}) + \varepsilon^{2}\lVert b_{i}\rVert^{2} = \lVert e_{i}\rVert^{2}\big(1 + 4W(e)(2\varepsilon\eta_{i} + \varepsilon^{2}\lVert b_{i}\rVert^{2})\big), 
\end{align}
and $\operatorname{Re} H(b, e) = \eta_{1} + \eta_{2} + \eta_{3}$ there follows
\begin{align}\label{eq:numdenfull2}
\begin{aligned}
\prod_{i=1}^{3}\frac{\lVert e_{i} + \varepsilon b_{i}\rVert^{2}}{\lVert e_{i}\rVert^{2}} &= 1 + 8W(e)\varepsilon\operatorname{Re} H(b, e) + \varepsilon^{2}\Big(4W(e)\lvert b\rvert^{2} + 64W(e)^{2}(\eta_{1}\eta_{2} + \eta_{2}\eta_{3} + \eta_{3}\eta_{1})\Big) + O(\varepsilon^{3}).
\end{aligned}
\end{align}
By \eqref{eq:derivativesC}, 
\begin{align}\label{dceb}
&dC_{e}(b) = \tfrac{1}{2}B(e\circledcirc e, b) = \tfrac{1}{2}B(\tau e, b) = -\tfrac{1}{2}H(b, e), &&d^{2}C_{e}(b, b) = B(b, e\circledcirc b) = -H(b, \tau\mathsf{L}(e)b). 
\end{align}
Since $C(e)= -1/(8W(e))$ is real it follows from \eqref{dceb} that 
\begin{align}
\begin{aligned}
C(e + \varepsilon b) &=C(e) +\varepsilon dC_{e}(b) + \tfrac{1}{2}\varepsilon^{2}d^{2}C_{e}(b, b) + O(\varepsilon^{3})\\
& = C(e) - \tfrac{1}{2}\varepsilon H(b, e) - \tfrac{1}{2}\varepsilon^{2}H(b, \tau\mathsf{L}(e)b) + O(\varepsilon^{3})\\
&= C(e)\big(1 + 4W(e)\varepsilon H(b, e) + 4W(e)\varepsilon^{2}H(b, \tau\mathsf{L}(e)b)\big) + O(\varepsilon^{3}),
\end{aligned}
\end{align}
which yields
\begin{align}\label{eq:numdenfull}
\begin{aligned}
\frac{|C(e + \varepsilon b)|^{2}}{C(e)^{2}} &= 1 + 8W(e)\varepsilon\operatorname{Re} H(b, e) + \varepsilon^{2}\Big(16W(e)^{2}|H(b, e)|^{2} + 8W(e)\operatorname{Re} H(b, \tau\mathsf{L}(e)b)\Big) + O(\varepsilon^{3}).
\end{aligned}
\end{align}
Because the first order terms in \eqref{eq:numdenfull2} and \eqref{eq:numdenfull} coincide, the coefficient of $\varepsilon^{2}$ in the quotient $W(e + \varepsilon b)$ is $W(e)$ times the difference of the coefficients of $\varepsilon^{2}$, and $\operatorname{Hess} W_{e}(b)$ is twice this coefficient, which gives \eqref{eq:hessW}. If $b \in U^{\perp}_{e}$, then $H(b, e) = 0$ and $\eta_{1} = \eta_{2} = \eta_{3} = 0$, so \eqref{eq:hessW} becomes \eqref{eq:hessR}. By Lemma \ref{hess2}, $JU^{\perp}_{e} = U^{\perp}_{e}$ and $\tau\mathsf{L}(e)$ anticommutes with $J$, so $\operatorname{Re} H(Jb, \tau\mathsf{L}(e)Jb) = -\operatorname{Re} H(b, \tau\mathsf{L}(e)b)$ for $b \in U^{\perp}_{e}$, and adding \eqref{eq:hessR} for $b$ and for $Jb$ gives \eqref{eq:hessJ}.

An element $w \in \mathbb C^{3}$ of the Lie algebra of $(\mathbb C^{\ast})^{3}$ generates the linear vector field $a \mapsto w \cdot a = (w_{1}a_{1}, w_{2}a_{2}, w_{3}a_{3})$ on $\mathfrak{g}^{3}$. Differentiating the identity $dW_{a}(w \cdot a) = 0$, which expresses the invariance of $W$, at $a = e$ in the direction $b$ and using $dW_{e} = 0$ gives $\operatorname{Hess} W_{e}(w \cdot e, b) = 0$. The vectors $w \cdot e$, $w \in \mathbb C^{3}$, span $U_{e}$, which proves the last claim.

\label{lem:secondorder}
Let $e\in \mathfrak{g}^{3}$ be a $\tau$-twisted idempotent at which $W$ assumes its maximum value $W(e) = \lVert \omega\rVert_{\ast}^{2}$.
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{so1} $\lvert \tau\mathsf{L}(e)b\rvert \leq \tfrac{1}{2}\lvert b\rvert$ for all $b \in U^{\perp}_{e}$; that is, on the orthogonal complement of the $(\mathbb C^{\ast})^{3}$-orbit, the twisted multiplication operator of the maximizer $e$ is bounded by $1/2$.
\item\label{so2} For $i \in \{1, 2, 3\}$ and every $v \in \mathfrak{g}$ with $H(v, e_{i}) = 0$,
\begin{align}\label{eq:clubs}
\sum_{a \in \{1, 2, 3\} \setminus \{i\}}\lVert [e_{a}, v]\rVert^{2} = \lvert e \circledcirc \iota_{i}(v)\rvert^{2} \leq \tfrac{1}{4}\lVert v\rVert^{2}.
\end{align}
\end{enumerate}

Write $f := \tau e$. By \eqref{eq:idemnorms} of Lemma \ref{thm:idem}, since $W(e) = \lVert \omega\rVert_{\ast}^{2}$,
\begin{align}\label{eq:efnorms}
H(e_{a}, e_{b}) = H(f_{a}, f_{b}) = \frac{\delta_{ab}}{4\lVert \omega\rVert_{\ast}^{2}}, \qquad a, b \in \{1, 2, 3\},
\end{align}
so that $\operatorname{Span}_{\mathbb C}\{e_{1}, e_{2}, e_{3}\}$ has complex dimension $3$. Because $e \circledcirc e = \tau e$ and $\tau$ is an order $2$ automorphism of $(\mathfrak{g}^{3}, \circledcirc)$ (Lemma \ref{lem:nahmbasic}\ref{nahm3}),
\begin{align}\label{eq:cyclicrelations}
e \circledcirc e = f, \qquad f \circledcirc f = \tau(e \circledcirc e) = e.
\end{align}
By Lemma \ref{lem:nahmbasic}\ref{nahm2} this means
\begin{align}\label{eq:cyclicrelations2}
&[e_{j}, e_{k}] = \tfrac{1}{2}f_{i}, && [f_{j}, f_{k}] = \tfrac{1}{2}e_{i},
\end{align}
for $(i, j, k)$ a cyclic permutation of $(1, 2, 3)$.
By \eqref{eq:cyclicrelations2} and the Jacobi identity,
\begin{align}\label{eq:cyclicrelations3}
\tfrac{1}{2}\sum_{a=1}^{3}[e_{a}, f_{a}] = [e_{1}, [e_{2}, e_{3}]] + [e_{2}, [e_{3}, e_{1}]] + [e_{3}, [e_{1}, e_{2}]] = 0.
\end{align}
Since $\tau e_{a} = f_{a}$ and $\tau f_{a} = e_{a}$, $Q(e_{a}) = -\operatorname{ad}(f_{a})\operatorname{ad}(e_{a})$ and $Q(f_{a}) = -\operatorname{ad}(e_{a})\operatorname{ad}(f_{a})$, so
\begin{align}
Q(e_{a}) - Q(f_{a}) = \operatorname{ad}(e_{a})\operatorname{ad}(f_{a}) - \operatorname{ad}(f_{a})\operatorname{ad}(e_{a}) = \operatorname{ad}([e_{a}, f_{a}]).
\end{align}
With \eqref{eq:cyclicrelations3} this yields
\begin{align}\label{eq:cyclicrelations4}
\sum_{a=1}^{3}Q(e_{a}) = \sum_{a=1}^{3}Q(f_{a}).
\end{align}
Since $[f_{a}, f_{m}] = \pm\tfrac{1}{2}e_{c}$ for $a \neq m$, where $c$ is the index in $\{1, 2, 3\}$ different from $a$ and $m$, by \eqref{eq:cyclicrelations2} and \eqref{eq:efnorms}, evaluating both sides of \eqref{eq:cyclicrelations4} on $f_{m}$ yields
\begin{align}\label{eq:sumrule}
\begin{aligned}
\sum_{a=1}^3\lVert [e_a,f_m]\rVert^2&=\sum_{a=1}^3H(Q(e_{a})f_{m}, f_{m}) = \sum_{a=1}^3H(Q(f_{a})f_{m}, f_{m})= \sum_{a=1}^3\lVert [f_a,f_m]\rVert^2= \frac{1}{8\lVert \omega\rVert_{\ast}^{2}}.
\end{aligned}
\end{align}
Fix $m$ and define
\begin{align}
v = f_{m} - 4\lVert \omega\rVert_{\ast}^{2}\sum_{a = 1}^{3}H(f_{m}, e_{a})e_{a},
\end{align}
so that, by \eqref{eq:efnorms}, $H(v, e_{a}) = 0$ for all $a \in \{1, 2, 3\}$ and $\lVert v\rVert^{2} = \frac{1}{4\lVert \omega\rVert_{\ast}^{2}} - 4\lVert \omega\rVert_{\ast}^{2}\sum_{a=1}^{3}|H(f_{m}, e_{a})|^{2}$.

For $a \in \{1, 2, 3\}$ there holds
\begin{align}
[e_{a}, f_{m}] = [e_{a}, v] + 4\lVert \omega\rVert_{\ast}^{2}\sum_{b \in \{1, 2, 3\}\setminus\{a\}}H(f_{m}, e_{b})[e_{a}, e_{b}],
\end{align}
and by \eqref{eq:cyclicrelations2}, for $b \neq a$, $[e_{a}, e_{b}] = \pm \tfrac{1}{2}f_{c}$, where $c$ is the index with $\{a, b, c\} = \{1, 2, 3\}$; as $b$ runs over the two indices different from $a$, so does $c$. The two summands are orthogonal, because by \eqref{basic4} and \eqref{eq:cyclicrelations2}, $H([e_{a}, v], f_{c}) = -H(v, [f_{a}, f_{c}]) = \mp \tfrac{1}{2}H(v, e_{b}) = 0$. Since $f_{1}, f_{2}, f_{3}$ are orthogonal of squared norm $1/(4\lVert \omega\rVert_{\ast}^{2})$ by \eqref{eq:efnorms},
\begin{align}\label{eq:rigidsplit}
\lVert [e_{a}, f_{m}]\rVert^{2} = \lVert [e_{a}, v]\rVert^{2} + \lVert \omega\rVert_{\ast}^{2}\sum_{b \in \{1, 2, 3\}\setminus\{a\}}|H(f_{m}, e_{b})|^{2}, \qquad a \in \{1, 2, 3\}.
\end{align}
Summing \eqref{eq:rigidsplit} over $a$ and using \eqref{eq:sumrule} gives
\begin{align}\label{rsp1}
\sum_{a=1}^{3}\lVert [e_{a}, v]\rVert^{2} = \frac{1}{8\lVert \omega\rVert_{\ast}^{2}} - 2\lVert \omega\rVert_{\ast}^{2}\sum_{a = 1}^{3}|H(f_{m}, e_{a})|^2 = \tfrac{1}{2}\lVert v\rVert^{2}.
\end{align}
On the other hand, summing \eqref{eq:clubs} over $i \in \{1, 2, 3\}$, in which each $a$ occurs twice, gives
\begin{align}\label{rsp2}
2\sum_{a=1}^{3}\lVert [e_{a}, v]\rVert^{2} \leq \tfrac{3}{4}\lVert v\rVert^{2}.
\end{align}
Combining \eqref{rsp1} and \eqref{rsp2} gives
\begin{align}
\lVert v\rVert^{2} \leq \tfrac{3}{4}\lVert v\rVert^{2},
\end{align}
so $v = 0$ and $f_{m} \in \operatorname{Span}_{\mathbb C}\{e_{1}, e_{2}, e_{3}\}$. Hence $\operatorname{Span}_{\mathbb C}\{e_{1}, e_{2}, e_{3}\}$ is $\tau$-stable, and by \eqref{eq:cyclicrelations2} it contains the brackets $[e_{j}, e_{k}] = \tfrac{1}{2}f_{i}$. It follows that the Lie subalgebra $\mathfrak{s}_{e}$ of $\mathfrak{g}$ generated by the components of $e$ equals $\operatorname{Span}_{\mathbb C}\{e_{1}, e_{2}, e_{3}\}$ and is $\tau$-stable; it is semisimple by Lemma \ref{thm:idem}\ref{idem3}. Being semisimple of dimension $3$, $\mathfrak{s}_{e}$ is isomorphic to $\mathfrak{sl}(2, \mathbb C)$.

\label{lem:schur}
\leavevmode\noindent
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{schur1} If $\mathfrak{g}$ is simple, every positive definite $\mathfrak{g}_{0}$-invariant Hermitian form is $\mathcal H = \kappa H$ for a unique $\kappa > 0$, and then $F_{\mathcal H} = \kappa^{-1}F$.
\item\label{schur2} If $\mathfrak{g}$ is reductive, the ideals $\mathfrak{z}, \mathfrak{s}_{1}, \dots, \mathfrak{s}_{r}$ are $\tau$-stable and pairwise $\mathcal H$-orthogonal for every positive definite $\mathfrak{g}_{0}$-invariant $\mathcal H$, $\mathfrak{k}_{k} := \mathfrak{s}_{k} \cap \mathfrak{g}_{0}$ is a compact real form of $\mathfrak{s}_{k}$, and $\mathcal H|_{\mathfrak{s}_{k}} = \kappa_{k}H_{k}$ with $\kappa_{k} > 0$, where $H_{k}$ is the form \eqref{eq:Hdef} of $\mathfrak{s}_{k}$.
\end{enumerate}

\label{thm:reductive}
Let $\mathfrak{g}$ be complex reductive and non-abelian, with compact real form $\mathfrak{g}_{0}$, and let $\mathcal H$ be a positive definite $\mathfrak{g}_{0}$-invariant Hermitian form, with $\kappa_{k}$ as in Lemma \ref{lem:schur}\ref{schur2}. Let $h_{k}^{\vee}$ be the dual Coxeter number of $\mathfrak{s}_{k}$ and $\lambda^{\ast} := \max_{1 \leq k \leq r}(\kappa_{k}h_{k}^{\vee})^{-1}$. Then
\begin{align}\label{eq:redbound}
\mathcal H([x, y], [x, y]) \leq \lambda^{\ast}\,\mathcal H(x, x)\,\mathcal H(y, y) \qquad \text{for all } x, y \in \mathfrak{g},
\end{align}
the constant is optimal, and for $x, y \neq 0$ equality holds if and only if $x$ and $y$ lie in a single ideal $\mathfrak{s}_{k}$ with $(\kappa_{k}h_{k}^{\vee})^{-1} = \lambda^{\ast}$ and satisfy there the equality condition of Theorem \ref{thm:A}.

Write $x = x_{0} + \sum_{k=1}^{r}x_{k}$ and $y = y_{0} + \sum_{k=1}^{r}y_{k}$ according to the decomposition of $\mathfrak{g}$, and put $a_{k} = \mathcal H(x_{k}, x_{k})$ and $b_{k} = \mathcal H(y_{k}, y_{k})$ for $0 \leq k \leq r$. Then $[x, y] = \sum_{k=1}^{r}[x_{k}, y_{k}]$, and by Lemma \ref{lem:schur} and Theorem \ref{thm:A} applied in each $\mathfrak{s}_{k}$,
\begin{align}\label{eq:chain}
\mathcal H([x, y], [x, y]) = \sum_{k=1}^{r}\mathcal H([x_{k}, y_{k}], [x_{k}, y_{k}]) \leq \sum_{k=1}^{r}\frac{a_{k}b_{k}}{\kappa_{k}h_{k}^{\vee}} \leq \lambda^{\ast}\sum_{k=1}^{r}a_{k}b_{k} \leq \lambda^{\ast}\Big(\sum_{k=0}^{r}a_{k}\Big)\Big(\sum_{k=0}^{r}b_{k}\Big),
\end{align}
which is \eqref{eq:redbound}. Equality is attained by an extremal pair of Theorem \ref{thm:A} in an ideal realizing $\lambda^{\ast}$. If equality holds with $x, y \neq 0$, then some $a_{k}b_{k} > 0$, and equality in the last step of \eqref{eq:chain} forces all the other components of $x$ and $y$ to vanish; the remaining equalities then give the stated condition.

Since the Hermitian inner product on $V$ is $\mathfrak{g}_{0}$-invariant, $\rho(\mathfrak{g}_{0})$ consists of skew-Hermitian operators, so $\rho(x)^{\dagger} = -\rho(\tau x)$ for $x \in \mathfrak{g}$. By \eqref{eq:repindex}, \eqref{eq:Bnorm}, and \eqref{eq:Hdef},
\begin{align}\label{eq:frobeniusH}
\operatorname{tr} \rho(x)\rho(y)^{\dagger} = -\ell_{\rho}(x, \tau y) = \frac{\ell_{\rho}}{2h^\vee}H(x, y).
\end{align}
By \eqref{eq:frobeniusH},
\begin{align}\label{eq:fh1}
&\lVert \rho(x)\rVert_{F}^{2} = \operatorname{tr} \rho(x)\rho(x)^{\dagger} = \frac{\ell_{\rho}}{2h^\vee}\lVert x\rVert^{2},&&\lVert \rho([x, y])\rVert_{F}^{2} = \operatorname{tr} \rho([x, y])\rho([x, y])^{\dagger} = \frac{\ell_{\rho}}{2h^\vee}\lVert [x, y]\rVert^{2}.& 
\end{align}
By \eqref{eq:fh1}, since $\rho$ is injective and $[\rho(x), \rho(y)] = \rho([x, y])$, for $x, y \in \mathfrak{g}\setminus\{0\}$
\begin{align}\label{eq:frobeniusratio}
\begin{aligned}
\frac{\lVert [\rho(x), \rho(y)]\rVert_{F}^{2}}{\lVert \rho(x)\rVert_{F}^{2}\lVert \rho(y)\rVert_{F}^{2}} = \frac{2h^\vee}{\ell_{\rho}}F(x, y),
\end{aligned}
\end{align}
and Theorem \ref{thm:B}, with the optimal constant $(2h^\vee/\ell_{\rho})(1/h^\vee) = 2/\ell_{\rho}$ and the stated equality case, follows from \eqref{eq:frobeniusratio} and Theorem \ref{thm:A}.

\label{cor:matrix}
Let $\lVert X\rVert_{F}^{2} = \operatorname{tr} XX^{\dagger}$ be the Frobenius norm of the complex matrix $X$, and let $e_{1}, \dots, e_{n}$ be the standard basis of $\mathbb C^{n}$. In each item, equality is characterized for nonzero $X$ and $Y$ (respectively $A$ and $B$).
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{mat1} (Böttcher--Wenzel) $\lVert [X, Y]\rVert_{F}^{2} \leq 2\lVert X\rVert_{F}^{2}\lVert Y\rVert_{F}^{2}$ for $X, Y \in \mathfrak{gl}(n, \mathbb C)$, $n \geq 2$, with equality if and only if $\operatorname{tr} XY^{\dagger} = 0$ and there is a unitary matrix $U$ such that $UXU^{-1}$ and $UYU^{-1}$ lie in the subalgebra $\mathfrak{sl}(2, \mathbb C) \subset \mathfrak{gl}(n, \mathbb C)$ of trace-free matrices acting on $\operatorname{Span}_{\mathbb C}\{e_{1}, e_{2}\}$ and annihilating $e_{3}, \dots, e_{n}$; for example $X = E_{12}$, $Y = E_{21}$. This is the characterization of Cheng, Vong, and Wenzel \cite[Theorems~3.1 and 3.2]{Cheng-Vong-Wenzel}.
\item\label{mat2} $\lVert [X, Y]\rVert_{F}^{2} \leq 2\lVert X\rVert_{F}^{2}\lVert Y\rVert_{F}^{2}$ for $X, Y \in \mathfrak{sp}(2n, \mathbb C)$, $n \geq 1$, with equality if and only if $\operatorname{tr} XY^{\dagger} = 0$ and there is $U \in Sp(2n, \mathbb C) \cap U(2n)$ such that $UXU^{-1}$ and $UYU^{-1}$ lie in the subalgebra $\mathfrak{sp}(2, \mathbb C) \subset \mathfrak{sp}(2n, \mathbb C)$ acting on $\operatorname{Span}_{\mathbb C}\{e_{1}, e_{n+1}\}$ and annihilating the other basis vectors.
\item\label{mat3} For complex skew-symmetric $X, Y \in \mathfrak{so}(n, \mathbb C)$, $n \geq 3$,
\begin{align}\label{eq:BImatrix}
\lVert [X, Y]\rVert_{F}^{2} \leq c_{n}\lVert X\rVert_{F}^{2}\lVert Y\rVert_{F}^{2}, \qquad c_{3} = \tfrac{1}{2}, \quad c_{n} = 1 \ (n \geq 4).
\end{align}
For $n = 3$ equality holds if and only if $\operatorname{tr} XY^{\dagger} = 0$. For $n \geq 4$ equality holds if and only if $\operatorname{tr} XY^{\dagger} = 0$ and there is $U \in SO(n)$ such that $UXU^{-1}$ and $UYU^{-1}$ lie in one of the two simple ideals of the subalgebra $\mathfrak{so}(4, \mathbb C) \subset \mathfrak{so}(n, \mathbb C)$ acting on $\operatorname{Span}_{\mathbb C}\{e_{1}, \dots, e_{4}\}$ and annihilating $e_{5}, \dots, e_{n}$. For real skew-symmetric matrices \eqref{eq:BImatrix} is the inequality of Bloch--Iserles \cite{Bloch-Iserles}.
\item\label{mat4} (Chern--do Carmo--Kobayashi) $\lVert [A, B]\rVert_{F}^{2} \leq 2\lVert A\rVert_{F}^{2}\lVert B\rVert_{F}^{2}$ for real symmetric $n \times n$ matrices $A$ and $B$, with equality if and only if there are $O \in O(n)$ and $a, b \in \mathbb R$ such that $OAO^{-1} = a(E_{11} - E_{22})$ and $OBO^{-1} = b(E_{12} + E_{21})$.
\end{enumerate}

The inequalities in \ref{mat1}--\ref{mat3} follow from Theorem \ref{thm:B} and the indices just computed, using Corollary \ref{thm:reductive} for $\mathfrak{gl}(n, \mathbb C) = \mathbb C I \oplus \mathfrak{sl}(n, \mathbb C)$ and for $\mathfrak{so}(4, \mathbb C)$. For the equality cases, take on $\mathfrak{sl}(n, \mathbb C)$, $\mathfrak{sp}(2n, \mathbb C)$, and $\mathfrak{so}(n, \mathbb C)$ the compact conjugation $\tau X = -X^{\dagger}$, whose compact groups act by conjugation through $SU(n)$, $Sp(2n, \mathbb C) \cap U(2n)$, and $SO(n)$. On each of these Lie algebras $H$ is a positive multiple of $\operatorname{tr} XY^{\dagger}$, so the condition $H(x, y) = 0$ of Theorem \ref{thm:A} is $\operatorname{tr} XY^{\dagger} = 0$. By Theorem \ref{thm:B}, equality holds exactly for the images of the equality pairs of Theorem \ref{thm:A}. By Lemma \ref{lem:lower}\ref{lower3}, every $\tau$-stable subalgebra $\mathfrak{s} \simeq \mathfrak{sl}(2, \mathbb C)$ of Dynkin index $1$ is conjugate under the compact group $G_{0}$ to the subalgebra $\mathfrak{s}_{\theta}$ attached to the highest root, so it suffices to identify this subalgebra in each case. For $\mathfrak{sl}(n, \mathbb C)$, $n \geq 2$, the subalgebra attached to the highest root is the subalgebra $\mathfrak{sl}(2, \mathbb C)$ of \ref{mat1}; by Corollary \ref{thm:reductive}, equality in $\mathfrak{gl}(n, \mathbb C)$ forces $X, Y \in \mathfrak{sl}(n, \mathbb C)$. For $\mathfrak{sp}(2n, \mathbb C)$, with $\Omega$ as above, the highest root is $2\epsilon_{1}$ and its subalgebra is the subalgebra $\mathfrak{sp}(2, \mathbb C)$ of \ref{mat2}. For $\mathfrak{so}(n, \mathbb C)$ with $n \geq 5$, the subalgebra attached to the highest root $\epsilon_{1} + \epsilon_{2}$ lies, together with the one attached to $\epsilon_{1} - \epsilon_{2}$, in a subalgebra $\mathfrak{so}(4, \mathbb C)$ acting on a $4$-dimensional subspace spanned by real vectors, as one of its two simple ideals, which gives \ref{mat3} after conjugation by $SO(n)$. For $n = 4$, Corollary \ref{thm:reductive} applies to the two ideals of $\mathfrak{so}(4, \mathbb C) \simeq \mathfrak{sl}(2, \mathbb C) \oplus \mathfrak{sl}(2, \mathbb C)$, each of which carries the constant $1$; for $n = 3$, $\mathfrak{so}(3, \mathbb C) \simeq \mathfrak{sl}(2, \mathbb C)$ is its own unique subalgebra isomorphic to $\mathfrak{sl}(2, \mathbb C)$, so the only condition is $\operatorname{tr} XY^{\dagger} = 0$. The pairs $E_{12}, E_{21}$ and, for $\mathfrak{so}(n, \mathbb C)$, the real matrices
\begin{align}\label{eq:BIextremal}
\begin{aligned}
&n = 3: & X &= E_{12} - E_{21}, & Y &= E_{23} - E_{32}, & \frac{\lVert [X, Y]\rVert_{F}^{2}}{\lVert X\rVert_{F}^{2}\lVert Y\rVert_{F}^{2}} &= \frac{2}{2\cdot 2} = \frac{1}{2},\\
&n \geq 4: & X &= E_{12} - E_{21} + E_{34} - E_{43}, & Y &= E_{13} - E_{31} - E_{24} + E_{42}, & \frac{\lVert [X, Y]\rVert_{F}^{2}}{\lVert X\rVert_{F}^{2}\lVert Y\rVert_{F}^{2}} &= \frac{16}{4\cdot 4} = 1,
\end{aligned}
\end{align}
padded by zeros for $n > 4$, attain equality, as the values in \eqref{eq:BIextremal} show.

For \ref{mat4}, $iA$ and $iB$ lie in $\mathfrak{u}(n)$ and $\lVert [iA, iB]\rVert_{F} = \lVert [A, B]\rVert_{F}$, so the inequality is the restriction of \ref{mat1}. If equality holds, then by \ref{mat1}, $\operatorname{tr} AB = 0$ and there is a $2$-dimensional subspace $P \subset \mathbb C^{n}$ such that $A$ and $B$ vanish on its Hermitian orthogonal complement and are trace-free on $P$. A real symmetric matrix of rank one is not trace-free on a subspace containing its range, so $P$ is the sum of the ranges of $A$ and $B$, which is the complexification of a real plane. After conjugation by an element of $O(n)$, $P = \operatorname{Span}_{\mathbb C}\{e_{1}, e_{2}\}$, and $A$ and $B$ are trace-free real symmetric $2 \times 2$ blocks, orthogonal for the trace form. A rotation of this plane makes $A = a(E_{11} - E_{22})$, and then $B = b(E_{12} + E_{21})$. Conversely, for these matrices $\lVert [A, B]\rVert_{F}^{2} = 8a^{2}b^{2} = 2\lVert A\rVert_{F}^{2}\lVert B\rVert_{F}^{2}$.

\label{lem:critFK}
\leavevmode\noindent
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{critF} $(x, y) \in (\mathfrak{g} \setminus \{0\})^{2}$ is a critical point of $F$ if and only if 
\begin{align}\label{eq:F}
Q(y)x = F(x,y)\lVert y\rVert^2 x, \qquad Q(x)y = F(x,y)\lVert x\rVert^2 y .
\end{align}
If $(x,y)\in\mathrm{Crit}^*(F)$, then $H(x, y) = 0$ and $(x,y,\tau[x,y])\in\mathrm{Crit}^*(W)$, with $W(x,y,\tau[x,y])=F(x,y)$.
\item\label{critK} $(x, y) \in \mathscr{V}(\mathfrak{g})$ is a critical point of $\mathscr{K}$ if and only if
\begin{align}\label{eq:K}
Q(y)x = \mathscr{K}(x, y)\big(\lVert y\rVert^{2}x - H(x, y)y\big), \qquad Q(x)y = \mathscr{K}(x, y)\big(\lVert x\rVert^{2}y - H(y, x)x\big).
\end{align}
\item\label{corr3} If $H(x, y) = 0$, then $(x, y)$ is a critical point of $\mathscr{K}$ if and only if it is a critical point of $F$, and $(x, y)$ is a critical point of $\mathscr{K}$ if and only if $\operatorname{Span}_{\mathbb C}\{x, y\}$ is a critical point of $\mathscr{K}$ on $\operatorname{Gr}(2, \mathfrak{g})$.
\item\label{corr2} If $a \in\mathrm{Crit}^*(W)$, then $(a_{j}, a_{k})\in\mathrm{Crit}^*(F)$ and $F(a_{j}, a_{k}) = W(a)$ for $j \neq k \in \{1, 2, 3\}$.
\end{enumerate}

Let $\beta = jh^\vee$. For \ref{sl2crit2}, use the coordinates of the proof of Lemma \ref{lem:sl2str}\ref{sl2b}, in which $\tau$ acts by complex conjugation of coefficient vectors because the $z_{a}$ lie in $\mathfrak{g}_{0}$. Since $H(x, y) = \beta\,x\cdot\bar{y} = 0$, the identity $a \times (b \times c) = b(a \cdot c) - c(a \cdot b)$ gives
\begin{align}\label{eq:triplecross}
\bar{y}\times(x \times y) = (\bar{y}\cdot y)\,x, \qquad -\bar{x}\times(x \times y) = (\bar{x}\cdot x)\,y,
\end{align}
and these are the coefficient vectors of $Q(y)x = [\tau y, [x, y]]$ and $Q(x)y = -[\tau x, [x, y]]$. Since $\bar{y}\cdot y = \lVert y\rVert^{2}/\beta$ and $F(x, y) = 1/\beta$ by \eqref{eq:sl2norm}, \eqref{eq:triplecross} is \eqref{eq:F}. Claim \ref{sl2crit1} follows from \ref{sl2crit2} and Lemma \ref{lem:critFK}\ref{corr3}, since every plane in $\mathfrak{s}$ has an $H$-orthogonal basis. For \ref{sl2crit3}, let $z := (z_{1}, z_{2}, z_{3})$. By \eqref{eq:xirelations} and Lemma \ref{lem:nahmbasic}\ref{nahm2}, $z \circledcirc z = 2z$, and $\tau z = z$ because the $z_{a}$ lie in $\mathfrak{g}_{0}$, so $e = \tfrac{1}{2}z$ satisfies $e \circledcirc e = \tfrac{1}{2}z = \tau e$. Since $\lVert e_{a}\rVert^{2} = \beta/4$ for $a \in \{1, 2, 3\}$, \eqref{eq:idemnorms} gives the values.

\label{rem:meshcheryakov}
For planes in $\mathfrak{g}_{0}$, Lemma \ref{thm:sl2crit}\ref{sl2crit1} and its converse are in \cite[Proposition~1 and Theorems~1, 2, and~4]{Meshcheryakov}: the critical points of the sectional curvature of $(G_{0}, -B)$ with nonzero critical value are the planes contained in subalgebras of $\mathfrak{g}_{0}$ isomorphic to $\mathfrak{su}(2)$, and the critical value on such a plane is $1/(4jh^\vee)$, where $j$ is the Dynkin index of the complexification of the subalgebra. The converse follows from Lemma \ref{lem:critFK}. For $x, y \in \mathfrak{g}_{0}$ both sides of \eqref{eq:K} lie in $\mathfrak{g}_{0}$, and $\operatorname{Re} H$ restricts to $-B$ on $\mathfrak{g}_{0}$, so a pair $(x, y) \in \mathfrak{g}_{0}^{2}$ orthonormal with respect to $-B$ is a critical point of the restriction of $\mathscr{K}$ to $\mathscr{V}(\mathfrak{g}_{0})$ if and only if it satisfies \eqref{eq:K}, which, since $\tau$ fixes $x$ and $y$, reads $[y, z] = \mathscr{K}(x, y)x$ and $[z, x] = \mathscr{K}(x, y)y$ with $z := [x, y]$; these are the criticality conditions of \cite[Proposition~1]{Meshcheryakov}. If $\mathscr{K}(x, y) \neq 0$, they show that $x$, $y$, and $z$ span a subalgebra of $\mathfrak{g}_{0}$ isomorphic to $\mathfrak{su}(2)$, whose complexification is $\tau$-stable, so $\mathscr{K}(x, y) = 1/(jh^\vee)$ by \eqref{eq:sl2norm}. In \cite[Theorem~4]{Meshcheryakov} the critical value is written $3/\sum_{s=1}^{m}n_{s}(n_{s}+1)(n_{s}+2)$, where $n_{1}+1, \dots, n_{m}+1$ are the dimensions of the irreducible summands of $\mathfrak{g}_{0}$ under the subalgebra; this agrees with $1/(4jh^\vee)$ because, by \eqref{eq:indexweights}, the Dynkin index of the irreducible $(n+1)$-dimensional representation of $\mathfrak{sl}(2, \mathbb C)$ is $n(n+1)(n+2)/6$, so $\sum_{s=1}^{m}n_{s}(n_{s}+1)(n_{s}+2)$ is $6$ times the Dynkin index $2jh^\vee$ of the restriction of the adjoint representation of $\mathfrak{g}$ to the complexified subalgebra.

For complex planes this description fails. If $\mu_{1}, \mu_{2}, \mu_{3} \in \Phi$ are long roots with $\mu_{1} + \mu_{2} + \mu_{3} = 0$ and $0 \neq e_{a} \in \mathfrak{g}_{\mu_{a}}$ for $a \in \{1, 2, 3\}$, then $H(e_{1}, e_{2}) = 0$, and by Lemmas \ref{thm:roottriangle} and \ref{lem:critFK}\ref{corr2},\ref{corr3} the plane $\operatorname{Span}_{\mathbb C}\{e_{1}, e_{2}\}$ is a critical point of $\mathscr{K}$ on $\operatorname{Gr}(2, \mathfrak{g})$ with critical value $1/(2h^\vee)$; but $[e_{a}, [e_{1}, e_{2}]] \in \mathfrak{g}_{\mu_{a} - \mu_{3}} = 0$ for $a \in \{1, 2\}$, so $e_{1}$, $e_{2}$, and $[e_{1}, e_{2}]$ span a nilpotent subalgebra, and the plane lies in no subalgebra isomorphic to $\mathfrak{sl}(2, \mathbb C)$.

\label{thm:roottriangle}
Let $\mu_{1}, \mu_{2}, \mu_{3} \in \Phi$ satisfy $\mu_{1} + \mu_{2} + \mu_{3} = 0$, and let $0 \neq e_{a} \in \mathfrak{g}_{\mu_{a}}$ for $a \in \{1, 2, 3\}$.
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{tri1} $(e_{1}, e_{2}, e_{3}) \in \mathrm{Crit}^*(W)$.
\item\label{tri2} If $\mu_{a} - \mu_{b} \notin \Phi$ for all $a \neq b$, then the $\mu_{a}$ have a common length, $\mathfrak{s} := \operatorname{Span}_{\mathbb C}\{t_{\mu_{1}}, t_{\mu_{2}}\} \oplus \bigoplus_{a=1}^{3}(\mathfrak{g}_{\mu_{a}} \oplus \mathfrak{g}_{-\mu_{a}})$ is a $\tau$-stable subalgebra isomorphic to $\mathfrak{sl}(3, \mathbb C)$ and having Dynkin index $j = 2/(\mu_{1}, \mu_{1})$, and
\begin{align}\label{eq:trianglevalue}
W(e_{1}, e_{2}, e_{3}) = \frac{(\mu_{1}, \mu_{1})}{4h^\vee} = \frac{1}{2jh^\vee}.
\end{align}
\item\label{tri3} The hypothesis of \ref{tri2} holds if the $\mu_{a}$ are long, and then $W(e_{1}, e_{2}, e_{3}) = 1/(2h^\vee)$. If the $\mu_{a}$ have a common length, the hypothesis of \ref{tri2} fails only for short roots of $G_{2}$, for which $\mu_{a} - \mu_{b}$ is a long root.
\end{enumerate}

\label{thm:morse}
Let $e \in \mathbb{Idem}_{\tau}(\mathfrak{g}^{3}, \circledcirc)$ be the $\tau$-twisted idempotent of Lemma \ref{thm:sl2crit}\ref{sl2crit3}, let $n_{d}$ be as in \eqref{eq:sperpdecomp}, and let $D = 3(\dim_{\mathbb C}\mathfrak{g} - 1)$ be as above.
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{morse1} On $\mathfrak{g}^{3} = \mathfrak{g} \otimes \mathbb C^{3}$, $\tau\mathsf{L}(e) = \tfrac{1}{2}\tau M$, where
\begin{align}\label{eq:spinorbit}
M := \sum_{l=1}^{3}\operatorname{ad}(z_{l})\otimes T_{l}, \qquad T_{l}v := \mathsf{c}_{l} \times v, \quad v \in \mathbb C^{3}.
\end{align}
The operator $M$ is complex linear, $H$-Hermitian, and commutes with $\tau$, and its eigenvalues on the summands of $V(d) \otimes \mathbb C^{3} \simeq V(d+2) \oplus V(d) \oplus V(d-2)$ (for $d \geq 2$) are $-\tfrac{d}{2}$, $1$, and $\tfrac{d}{2}+1$; for $d = 1$ they are $-\tfrac{1}{2}$ on $V(3)$ and $1$ on $V(1)$, and for $d = 0$, $M = 0$. On each eigenspace of $M$ with eigenvalue $m$, $\tau\mathsf{L}(e)$ has eigenvalues $\pm\tfrac{m}{2}$, each with real multiplicity equal to the complex dimension of the eigenspace.
\item\label{morse2} The coindex, nullity, and index of the critical point $[e] \in \mathcal{P}$ of $W$ are
\begin{align}\label{eq:morseindex}
\begin{aligned}
\operatorname{coind} &= n_{2} + \sum_{d \geq 3}(2d+2)n_{d}, \qquad \operatorname{null} = 6 + 2n_{1} + 8n_{2} + \sum_{d \geq 3}(d+1)n_{d},\\
\operatorname{ind} &= D + 3n_{0} + 4n_{1}.
\end{aligned}
\end{align}
\item\label{morse3} The Hessian of $W$ at $[e]$ is negative semidefinite if and only if $j = 1$.
\item\label{morse4} $\operatorname{ind} = D$ if and only if the centralizer of $\mathfrak{s}$ in $\mathfrak{g}$ is trivial, which is the case if and only if $\mathfrak{s}$ is a distinguished subalgebra in the sense of Bala and Carter \cite[Section~8.2]{Collingwood-McGovern}. In particular $\operatorname{ind} = D$ for the principal subalgebra.
\end{enumerate}

\label{lem:rotation}
Let $\mathfrak{s}$, $z_{1}, z_{2}, z_{3}$, and $e$ be as in Theorem \ref{thm:morse}.
\begin{enumerate}[label=(\arabic*), ref=(\arabic*)]
\item\label{rot1} Each $R \in U(3)$ acts on $\mathfrak{g}^{3}$ as an $H$-unitary operator commuting with $J$ and preserving $\mathfrak{s}\otimes\mathbb C^{3}$ and $\mathfrak{s}^{\perp}\otimes\mathbb C^{3}$, $\tau R = \bar{R}\tau$, and
\begin{align}\label{eq:rotation}
(Ra) \circledcirc (Rb) = \det(R)\,\bar{R}(a \circledcirc b), \qquad a, b \in \mathfrak{g}^{3}.
\end{align}
If $R \in SU(3)$, then $Re$ is a $\tau$-twisted idempotent and $\tau\mathsf{L}(Re)R = R\,\tau\mathsf{L}(e)$.
\item\label{rot2} Every nonzero $\tau$-twisted idempotent whose components lie in $\mathfrak{s}$ equals $Re$ for a unique $R \in SU(3)$.
\item\label{rot3} The conclusions \ref{morse2}--\ref{morse4} of Theorem \ref{thm:morse} hold at the image in $\mathcal{P}$ of every nonzero $\tau$-twisted idempotent whose components lie in $\mathfrak{s}$.
\end{enumerate}

\label{ex:sl3}
Let $\mathfrak{g} = \mathfrak{sl}(3, \mathbb C)$, viewed as trace-free $3\times 3$ complex matrices, and $\mathfrak{g}_{0} = \mathfrak{su}(3)$, so $h^\vee = 3$, $D = 21$, and $H(X, Y) = 6\operatorname{tr} XY^{\dagger}$. There are two conjugacy classes of subalgebras isomorphic to $\mathfrak{sl}(2, \mathbb C)$: the long-root subalgebras, with $j = 1$ and $\mathfrak{sl}(3, \mathbb C) = V(2) \oplus 2V(1) \oplus V(0)$, and the principal subalgebra $\mathfrak{so}(3, \mathbb C)$, with $j = 4$ and $\mathfrak{sl}(3, \mathbb C) = V(2) \oplus V(4)$. By Lemma \ref{thm:sl2crit} and Theorem \ref{thm:morse} they yield critical values $\tfrac{1}{3}$ and $\tfrac{1}{12}$ of $F$, $\mathscr{K}$, and $W$, and at the corresponding critical points of $W$ on $\mathcal{P}$ the triple (coindex, nullity, index) equals $(0, 10, 32)$ and $(10, 11, 21)$. In the first case the nullity is the dimension $6 + 2n_{1} = 10$ of the manifold of maximum points (Corollary \ref{cor:morsebott}); in the second the index is $D$, as Theorem \ref{thm:morse}\ref{morse4} predicts for the principal subalgebra. The root vectors of the long roots $\epsilon_{1} - \epsilon_{2}$, $\epsilon_{2} - \epsilon_{3}$, $\epsilon_{3} - \epsilon_{1}$ give critical points of the type of Lemma \ref{thm:roottriangle}: for $x = E_{12}$ and $y = E_{23}$, $H(x, y) = 0$, $[x, y] = E_{13}$, and
\begin{align}\label{eq:sl3critical}
Q(y)x = [-E_{32}, E_{13}] = E_{12} = \tfrac{1}{6}\lVert y\rVert^{2}x, \qquad Q(x)y = [E_{21}, E_{13}] = E_{23} = \tfrac{1}{6}\lVert x\rVert^{2}y,
\end{align}
so by \eqref{eq:sl3critical} and Lemma \ref{lem:critFK}, $(x, y) \in \mathrm{Crit}^*(F)$ with $F(x, y) = \tfrac{1}{6}$. By Lemma \ref{lem:critFK}\ref{critF}, $(x, y, -E_{31}) \in \mathrm{Crit}^*(W)$, with critical value $\tfrac{1}{6} = 1/(2h^\vee)$, as in \eqref{eq:trianglevalue}, and the subalgebra generated by $E_{12}$, $E_{23}$, $E_{31}$ is all of $\mathfrak{sl}(3, \mathbb C)$, in accord with Lemma \ref{thm:idem}\ref{idem3}.

\label{ex:g2}
Let $\mathfrak{g}$ be of type $G_{2}$, so $h^\vee = 4$ and $D = 39$. Its four conjugacy classes of subalgebras isomorphic to $\mathfrak{sl}(2, \mathbb C)$ are the long-root and short-root subalgebras, the principal subalgebra of a long-root $\mathfrak{sl}(3, \mathbb C)$ (subregular), and the principal subalgebra \cite{Collingwood-McGovern, Dynkin-semisimplesubalgebras}. Their Dynkin indices, the decompositions \eqref{eq:sperpdecomp}, the critical values $1/(4j)$, and the data \eqref{eq:morseindex} are:
\begin{align}\label{eq:g2table}
\begin{aligned}
&\text{long root:} && j = 1, && \mathfrak{s}^{\perp} = 4V(1) \oplus 3V(0), && \tfrac{1}{4}, && (\operatorname{coind}, \operatorname{null}, \operatorname{ind}) = (0, 14, 64),\\
&\text{short root:} && j = 3, && \mathfrak{s}^{\perp} = 2V(3) \oplus 3V(0), && \tfrac{1}{12}, && (\operatorname{coind}, \operatorname{null}, \operatorname{ind}) = (16, 14, 48),\\
&\text{subregular:} && j = 4, && \mathfrak{s}^{\perp} = V(4) \oplus 2V(2), && \tfrac{1}{16}, && (\operatorname{coind}, \operatorname{null}, \operatorname{ind}) = (12, 27, 39),\\
&\text{principal:} && j = 28, && \mathfrak{s}^{\perp} = V(10), && \tfrac{1}{112}, && (\operatorname{coind}, \operatorname{null}, \operatorname{ind}) = (22, 17, 39).
\end{aligned}
\end{align}
The decompositions in \eqref{eq:g2table} follow from the values of the roots on the coroot of a long, respectively short, root, from $\mathfrak{g} = \mathfrak{sl}(3, \mathbb C) \oplus \mathbb C^{3} \oplus (\mathbb C^{3})^{\ast}$ for a long-root $\mathfrak{sl}(3, \mathbb C)$, and from Kostant's theorem that the principal subalgebra decomposes $\mathfrak{g}$ according to the exponents $1$, $5$ \cite{Kostant-triples}. The subregular and principal subalgebras are distinguished, and the index is $D$ for both, in accord with Theorem \ref{thm:morse}\ref{morse4}. For three short roots $\mu_{1}, \mu_{2}, \mu_{3}$ of $G_{2}$ with sum zero, the hypothesis $\mu_{a} - \mu_{b} \notin \Phi$ of Lemma \ref{thm:roottriangle}\ref{tri2} fails, and the corresponding root vectors $e_{1}, e_{2}, e_{3}$ generate all of $\mathfrak{g}$. Indeed, the subalgebra they generate contains $[\mathfrak{g}_{\mu_{b}}, \mathfrak{g}_{\mu_{c}}] = \mathfrak{g}_{-\mu_{a}}$ for $\{a, b, c\} = \{1, 2, 3\}$, hence all six short root spaces, and then $[\mathfrak{g}_{\mu_{a}}, \mathfrak{g}_{-\mu_{b}}] = \mathfrak{g}_{\mu_{a} - \mu_{b}}$ for $a \neq b$ \cite[Proposition~8.4]{Humphreys}; the six roots $\mu_{a} - \mu_{b}$, $a \neq b$, are distinct and long, so they are all the long roots of $G_{2}$, and the brackets $[\mathfrak{g}_{\alpha}, \mathfrak{g}_{-\alpha}]$, $\alpha \in \Phi$, span $\mathfrak{h}$.
